import React, { useState, useEffect } from 'react';
import { calculateReadingTime, getWordCount } from '../utils/humanize';
import './PostForm.css';

const PostForm = ({ onSubmit, onUpdate, editingPost, onCancelEdit, loading }) => {
  const [formData, setFormData] = useState({
    title: '',
    content: '',
    author: '',
    publishedDate: new Date().toISOString().split('T')[0]
  });
  const [errors, setErrors] = useState({});
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    if (editingPost) {
      setFormData({
        title: editingPost.title,
        content: editingPost.content,
        author: editingPost.author,
        publishedDate: new Date(editingPost.publishedDate).toISOString().split('T')[0]
      });
      setErrors({});
    } else {
      setFormData({
        title: '',
        content: '',
        author: '',
        publishedDate: new Date().toISOString().split('T')[0]
      });
      setErrors({});
    }
  }, [editingPost]);

  const validateForm = () => {
    const newErrors = {};
    if (!formData.title.trim()) newErrors.title = 'Please provide a title for your story';
    if (!formData.content.trim()) newErrors.content = 'Write something inspiring for your readers';
    if (!formData.author.trim()) newErrors.author = 'Please share who wrote this story';
    if (!formData.publishedDate) newErrors.publishedDate = 'Please select a date';
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  const handleKeyDown = (e) => {
    if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
      handleSubmit(e);
    }
  };

  const handleSubmit = async (e) => {
    e?.preventDefault();
    if (!validateForm()) return;

    setSubmitting(true);
    try {
      if (editingPost) {
        await onUpdate(editingPost._id, formData);
      } else {
        await onSubmit(formData);
      }
      setFormData(prev => ({ ...prev, title: '', content: '', author: '' }));
    } catch (err) {
      setErrors({ submit: err.message || 'Something went wrong while saving your post.' });
    } finally {
      setSubmitting(false);
    }
  };

  const isEditing = Boolean(editingPost);
  const wordCount = getWordCount(formData.content);
  const readingTime = calculateReadingTime(formData.content);

  return (
    <section className="post-form-section fade-in" aria-labelledby="form-title">
      <div className={`post-form-card ${isEditing ? 'editing-active' : ''}`}>
        <header className="form-header">
          <div className="form-header-title-wrap">
            <h2 id="form-title" className="form-title">
              {isEditing ? '✏️ Edit Story' : '✍️ Write New Story'}
            </h2>
            <p className="form-subtitle">
              {isEditing 
                ? 'Refining an existing article' 
                : 'Share your perspective with the community'}
            </p>
          </div>
          {isEditing && (
            <button 
              type="button" 
              className="btn btn-secondary btn-sm" 
              onClick={onCancelEdit}
              title="Discard changes and exit edit mode"
            >
              <svg width="14" height="14" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
              Cancel
            </button>
          )}
        </header>

        {isEditing && (
          <div className="edit-banner">
            <span>You are editing <strong>"{editingPost.title}"</strong></span>
          </div>
        )}

        <form onSubmit={handleSubmit} className="post-form" noValidate>
          <div className="form-group">
            <label htmlFor="title" className="form-label">
              Story Title <span className="required" aria-hidden="true">*</span>
            </label>
            <input
              type="text"
              id="title"
              name="title"
              value={formData.title}
              onChange={handleChange}
              className={`form-input ${errors.title ? 'error' : ''}`}
              placeholder="e.g. 5 Habits That Transformed My Workflow"
              maxLength={200}
              disabled={submitting || loading}
              aria-invalid={errors.title ? 'true' : 'false'}
              aria-describedby={errors.title ? 'title-error' : undefined}
            />
            {errors.title && (
              <span id="title-error" className="form-error" role="alert">{errors.title}</span>
            )}
          </div>

          <div className="form-row-two-col">
            <div className="form-group">
              <label htmlFor="author" className="form-label">
                Author Name <span className="required" aria-hidden="true">*</span>
              </label>
              <input
                type="text"
                id="author"
                name="author"
                value={formData.author}
                onChange={handleChange}
                className={`form-input ${errors.author ? 'error' : ''}`}
                placeholder="e.g. Alex Rivera"
                maxLength={100}
                disabled={submitting || loading}
                aria-invalid={errors.author ? 'true' : 'false'}
                aria-describedby={errors.author ? 'author-error' : undefined}
              />
              {errors.author && (
                <span id="author-error" className="form-error" role="alert">{errors.author}</span>
              )}
            </div>

            <div className="form-group">
              <label htmlFor="publishedDate" className="form-label">
                Date <span className="required" aria-hidden="true">*</span>
              </label>
              <input
                type="date"
                id="publishedDate"
                name="publishedDate"
                value={formData.publishedDate}
                onChange={handleChange}
                className={`form-input ${errors.publishedDate ? 'error' : ''}`}
                disabled={submitting || loading}
                aria-invalid={errors.publishedDate ? 'true' : 'false'}
                aria-describedby={errors.publishedDate ? 'date-error' : undefined}
              />
              {errors.publishedDate && (
                <span id="date-error" className="form-error" role="alert">{errors.publishedDate}</span>
              )}
            </div>
          </div>

          <div className="form-group">
            <div className="form-label-row">
              <label htmlFor="content" className="form-label">
                Story Content <span className="required" aria-hidden="true">*</span>
              </label>
              {formData.content.length > 0 && (
                <span className="live-metric-pill">
                  {wordCount} words · {readingTime}
                </span>
              )}
            </div>
            <textarea
              id="content"
              name="content"
              value={formData.content}
              onChange={handleChange}
              onKeyDown={handleKeyDown}
              className={`form-textarea ${errors.content ? 'error' : ''}`}
              placeholder="Start typing your story, thoughts, or guide... Express yourself freely."
              rows={7}
              disabled={submitting || loading}
              aria-invalid={errors.content ? 'true' : 'false'}
              aria-describedby={errors.content ? 'content-error' : undefined}
            />
            {errors.content && (
              <span id="content-error" className="form-error" role="alert">{errors.content}</span>
            )}
          </div>

          {errors.submit && (
            <div className="form-error form-error-submit" role="alert">
              <svg width="18" height="18" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
              </svg>
              {errors.submit}
            </div>
          )}

          <div className="form-footer">
            <div className="form-actions">
              <button
                type="submit"
                className="btn btn-primary"
                disabled={submitting || loading}
              >
                {submitting && <span className="loading-spinner" aria-hidden="true"></span>}
                {isEditing ? '💾 Save Changes' : '🚀 Publish Story'}
              </button>
              {isEditing && (
                <button
                  type="button"
                  className="btn btn-outline"
                  onClick={onCancelEdit}
                  disabled={submitting || loading}
                >
                  Discard
                </button>
              )}
            </div>
            <span className="shortcut-hint">Press <kbd>Ctrl</kbd> + <kbd>Enter</kbd> to submit</span>
          </div>
        </form>
      </div>
    </section>
  );
};

export default PostForm;
